const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty = x => esc(JSON.stringify(x,null,2));
let entries=[], selected='', checker=null;
window.uiErrors=[];
window.addEventListener('error',e=>window.uiErrors.push(e.message));
window.addEventListener('unhandledrejection',e=>window.uiErrors.push(String(e.reason)));
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:r.ok,status:r.status,data:await r.json()};}
function message(text,warn=false){$('#message').innerHTML=text?`<div class="message ${warn?'warn':''}">${esc(text)}</div>`:'';}
const fields=[['kind','Kind'],['replay_status','Replay'],['licence_spdx','Licence'],['toolchain','Toolchain']];
function facets(){ $('#facets').innerHTML=fields.map(([key,label])=>`<fieldset><legend>${label}</legend>${[...new Set(entries.map(e=>e[key]))].map(value=>`<label><input type="checkbox" data-key="${key}" value="${esc(value)}">${esc(value==='real'?'Replayed by fvapi':value==='recorded'?'Recorded only':value.replace('leanprover/lean4:','Lean '))}</label>`).join('')}</fieldset>`).join(''); $('#facets').onchange=renderList;}
function renderList(){const filters={};document.querySelectorAll('#facets input:checked').forEach(c=>(filters[c.dataset.key]??=[]).push(c.value));const shown=entries.filter(e=>Object.entries(filters).every(([k,v])=>v.includes(e[k])));$('#count').textContent=`${shown.length} ${shown.length===1?'entry':'entries'}`;$('#entries').innerHTML=shown.map(e=>`<button class="entry ${e.id===selected?'selected':''}" data-id="${esc(e.id)}"><span class="id">${esc(e.id)}</span><strong>${esc(e.title)}</strong><p>${esc(e.claim)}</p><span class="badge ${e.replay_status==='recorded'?'recorded':''}">${e.replay_status==='recorded'?'Recorded • not re-run':'Replay available'}</span> <small>${esc(e.kind)}</small></button>`).join('')||'<p>No entries match. Clear a filter to see more results.</p>';document.querySelectorAll('.entry').forEach(b=>b.onclick=()=>{location.hash='entry/'+encodeURIComponent(b.dataset.id)});}
async function showEntry(id){selected=id;renderList();const r=await api('catalog/'+encodeURIComponent(id));if(!r.ok){const e=entries.find(e=>e.id===id);$('#detail').innerHTML=e?`<span class="id">${esc(e.id)}</span><h2>${esc(e.title)}</h2><p>${esc(e.claim)}</p><div class="notice"><strong>Recorded only. Not re-run by fvapi.</strong>This prototype has a catalog summary, but no full entry for this result. Choose another entry to inspect proof files.</div>`:`<h2>Entry not found</h2><p>Choose an entry from the catalog.</p>`;return;}renderDetail(r.data);}
function renderDetail(e){$('#detail').innerHTML=`<span class="id">${esc(e.id)} / ${esc(e.kind)}</span><h2>${esc(e.title)}</h2><p class="claim">${esc(e.claim)}</p>${e.replay.status==='recorded'?'<div class="notice"><strong>Recorded only. Not re-run by fvapi.</strong>This transcript comes from an earlier run at the source commit. Re-run the delivered proof yourself.</div>':'<p class="badge">Replay available • verify independently</p>'}<h3>Read the statement</h3>${e.statements.map(s=>`<code>${esc(s.file)}:${s.line}</code><pre>${esc(s.text)}</pre>`).join('')}<h3>Proof delivery</h3>${e.closure.map(f=>`<div class="file">${esc(f.path)} <span>(${f.bytes} bytes)</span><code>sha256 ${esc(f.sha256)}</code></div>`).join('')}<h3>Replay on your machine</h3><pre id="command">${esc(e.replay.command)}</pre><button id="copy" class="quiet">Copy replay command</button><dl><dt>Expected axioms</dt><dd>${esc(e.replay.expect_axioms.join(', ')||'None')}</dd><dt>Toolchain</dt><dd>${esc(e.toolchain)}</dd><dt>Dependencies</dt><dd>${esc(e.requires.join(', '))}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(n=>`${esc(n.name)}: ${esc(n.spdx)}<br>${esc(n.source)}`).join('<br>'):'No third-party notices in this entry.'}</dd><dt>Source</dt><dd>${esc(e.source.repo)}<br>Commit ${esc(e.source.commit)}<br>${e.source.paths.map(esc).join('<br>')}</dd></dl>${e.replay.transcript?`<h3>Recorded transcript</h3><pre>${esc(e.replay.transcript)}</pre>`:''}<div class="actions"><a href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download proof bundle</a>${e.check?'<a href="#check">Check your input</a>':''}</div>`;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy').textContent='Command copied';}catch{message('Copy is unavailable. Select and copy the replay command above.',true);}};}
async function lookup(value,type='auto'){let key=type==='auto'?(/^[a-f0-9]{64}$/i.test(value)?'artifact_sha256':/^[\w-]+\.[\w.-]+$/.test(value)?'spec_id':'statement'):type;const r=await api('lookup',{[key]:value});if(r.ok){message(`Exact match found: ${r.data.entry_id}. Inspect the statement before using this result.`);selected=r.data.entry_id;renderList();renderDetail(r.data.entry);}else{selected='';renderList();$('#detail').innerHTML='<div class="empty"><h2>No matching result</h2><p>Try another exact query or browse the catalog.</p></div>';message(r.status===404?'No exact match. This request was logged as demand. Try another entry id, artifact SHA256 or statement.':`Lookup failed: ${r.data.detail}. Check the query and try again.`,true);}}
async function loadExample(){const r=await api('catalog/vf.contrast-2x2');checker=r.data;$('#input').value=JSON.stringify(checker.check.example_input,null,2);}
async function runCheck(){let input;try{input=JSON.parse($('#input').value);}catch{$('#check-result').innerHTML='<div class="notice"><strong>The input is not valid JSON.</strong>Correct the JSON, then run the check again.</div>';return;}const r=await api('checks/'+encodeURIComponent($('#check-id').value),input);$('#check-result').innerHTML=!r.ok?`<div class="notice"><strong>${r.status===409?'This entry has no runnable checker.': 'The check could not run.'}</strong>${esc(r.data.detail)}. Select a checker entry and try again.</div>`:`<div class="outcome ${r.data.verdict==='reject'?'reject':''}"><h3>${r.data.verdict==='accept'?'Input accepted':'Input rejected'}</h3><p>${r.data.verdict==='accept'?'The input passed this checker. Re-run it locally before relying on the result.':'The input did not pass this checker. Review the weights and run it again.'}</p><p>Exit code ${r.data.exit_code} / ${r.data.elapsed_ms} ms / ${esc(r.data.ran_on)}</p><h3>Checker output</h3><pre>${pretty(r.data.output)}</pre><h3>Re-check locally</h3><pre>${typeof r.data.recheck==='string'?esc(r.data.recheck):pretty(r.data.recheck)}</pre></div>`;}
async function activity(kind){const r=await api(kind);const d=r.data;$('#activity').innerHTML=`<p class="log-intro">${kind==='demand'?'Unmatched requests show where the library can grow. No request is sent to an agent.':'Lookup and checker answers returned by the service.'}</p>${kind==='demand'?`<h3>Requests by key</h3>${d.by_key.map(x=>`<div class="log-row"><strong>${x.count} request${x.count===1?'':'s'}</strong><br><code>${esc(x.key)}</code></div>`).join('')||'<p>No unmatched requests. Run a lookup to explore the library.</p>'}<h3>Recent misses</h3>${d.misses.map(x=>`<div class="log-row"><strong>${esc(x.miss_id)}</strong> <time>${esc(x.at)}</time><pre>${pretty(x.query)}</pre></div>`).join('')}`:d.answers.map(x=>`<div class="log-row"><span class="badge">${esc(x.kind)}</span> <strong>${esc(x.entry_id)}</strong><p>${esc(x.answer_id)} / ${esc(x.at)}${x.verdict?' / '+esc(x.verdict):''}</p></div>`).join('')||'<p>No answers yet. Run a lookup or check an input.</p>'}`;}
async function route(){const hash=decodeURIComponent(location.hash.slice(1)||'catalog');const check=hash.startsWith('check'), logs=['demand','answers'].includes(hash);$('#catalog-view').hidden=check||logs;$('#check-view').hidden=!check;$('#activity-view').hidden=!logs;message('');if(hash.startsWith('entry/'))await showEntry(hash.slice(6));else if(hash==='entry')await showEntry('vf.contrast-2x2');else if(hash==='recorded')await showEntry(entries.find(e=>e.replay_status==='recorded'&&e.id==='fva.glm-iround')?.id||entries.find(e=>e.replay_status==='recorded').id);else if(hash==='lookup-hit'||hash==='lookup-miss'){const v=hash==='lookup-hit'?'vf.contrast-2x2':'missing.example';$('#query').value=v;await lookup(v,'spec_id');}else if(check){if(!checker)await loadExample();if(hash==='check-accept'||hash==='check-reject'||hash==='check-409'){ $('#check-id').value=hash==='check-409'?entries.find(e=>e.kind!=='checker').id:'vf.contrast-2x2';await loadExample();if(hash==='check-reject'){const x=JSON.parse($('#input').value);x.rows[0].weights[0]=1;$('#input').value=JSON.stringify(x,null,2);}await runCheck();}}else if(logs)await activity(hash);document.body.dataset.ready=hash;}
$('#lookup').onsubmit=async e=>{e.preventDefault();$('#catalog-view').hidden=false;$('#check-view').hidden=true;$('#activity-view').hidden=true;await lookup($('#query').value.trim(),$('#query-type').value);};
$('#check-form').onsubmit=e=>{e.preventDefault();runCheck();};$('#example').onclick=loadExample;$('#reset').onclick=()=>{document.querySelectorAll('#facets input').forEach(c=>c.checked=false);renderList();};
(async()=>{try{const r=await api('catalog');entries=r.data.entries;facets();renderList();$('#check-id').innerHTML=entries.map(e=>`<option value="${esc(e.id)}">${esc(e.id)} (${esc(e.kind)})</option>`).join('');window.addEventListener('hashchange',()=>route().catch(e=>message(e.message,true)));await route();}catch(e){message('The library could not load. Check the API connection and reload this page.',true);window.uiErrors.push(String(e));}})();
